// 缓存组件仅核具名事实与结果区间；完整经营资格由独立本域资金/历史门先验。
#include "resident/domains/commerce/private_shop_cached_receipt.hpp"
#include "resident/kernel/command_types.hpp"
#include <iostream>
using namespace hanmo::resident;
namespace {int failed=0;void check(bool ok,const char* name){if(!ok){++failed;std::cerr<<name<<'\n';}}
void cache(CommonStore& c,const StableId& kind,Integer sequence,ReceiptData details){auto id=c.next_id("result");if(!id.ok){++failed;return;}c.state().request_sequences.insert("owner",sequence);*c.state().request_sequences.find("owner")=sequence;c.state().history.push_back({c.tick(),kind,"owner",id.value,{}});auto r=std::make_shared<CommitResult>();r->kind=kind;r->result_id=id.value;r->tick=c.tick();r->revision=++c.state().identity.revision;r->details=std::make_shared<ReceiptDetails>(ReceiptDetails{std::move(details),{}});c.state().results.insert("owner:"+std::to_string(sequence),std::move(r));}}
int main(){CommonState state;ActorRecord actor;actor.id="owner";state.actors.insert(actor.id,actor);CommonStore common(std::move(state),std::make_shared<const CommonCatalog>());PrivateShopState shops;auto first=common.next_id("private_shop_capital");check(first.ok,"allocate source");PrivateShopCapitalFact funding;funding.id=first.value;funding.actor_id="owner";funding.tick=0;shops.capital.insert(funding.id,funding);check(common.append_fact({funding.id,"private_shop_capital_added","private_shops"}).ok,"append real header");InteractionEffect effect;effect.settlement_result=funding.id;cache(common,"private_shop_fund",1,effect);check(validate_private_shop_cached_results(common,&shops).ok,"original exact command source");check(!validate_private_shop_cached_results(common,nullptr).ok,"disabled module rejects command source");auto original=common.state().results;auto forged=std::make_shared<CommitResult>(**common.state().results.find("owner:1"));forged->kind="private_shop_open";*common.state().results.find("owner:1")=forged;check(!validate_private_shop_cached_results(common,&shops).ok,"wrong command kind rejects");common.state().results=original;auto changed=effect;changed.person_id="stranger";forged=std::make_shared<CommitResult>(**common.state().results.find("owner:1"));forged->details=std::make_shared<ReceiptDetails>(ReceiptDetails{changed,{}});*common.state().results.find("owner:1")=forged;check(!validate_private_shop_cached_results(common,&shops).ok,"extra effect field rejects");common.state().results=original;common.state().results.erase("owner:1");cache(common,"private_shop_fund",2,effect);check(!validate_private_shop_cached_results(common,&shops).ok,"later request cannot reuse source after first result boundary");{
 CommonState initial;ActorRecord person;person.id="owner";initial.actors.insert(person.id,person);CommonStore ended(std::move(initial),std::make_shared<const CommonCatalog>());PrivateShopState ledger;
 auto action=ended.next_id("action");check(action.ok,"allocate original operation");PrivateShopOperation operation;operation.id=action.value;operation.actor_id="owner";ledger.operations.insert(operation.id,operation);check(ended.append_fact({operation.id,"private_shop_operating_started","private_shops"}).ok,"operation source");auto source=ended.next_id("private_shop_day");check(source.ok,"allocate interruption");PrivateShopDayResult day;day.id=source.value;day.operation_id=operation.id;day.actor_id="owner";day.completed=false;day.reason="PrivateShopAttendanceUnavailable";ledger.operating_results.insert(day.id,day);ledger.operations.find(operation.id)->result_fact_id=day.id;check(ended.append_fact({day.id,"private_shop_operating_interrupted","private_shops"}).ok,"interruption source");AdvanceDetails advance;ActionCompletion completion;completion.completed=true;completion.success=false;completion.code=day.reason;advance.completed_actions.insert(operation.id,completion);cache(ended,"advance",1,advance);check(validate_private_shop_cached_results(ended,&ledger).ok,"interrupted action is finished with failure");auto forged=std::make_shared<CommitResult>(**ended.state().results.find("owner:1"));advance.completed_actions.find(operation.id)->completed=false;forged->details=std::make_shared<ReceiptDetails>(ReceiptDetails{advance,{}});*ended.state().results.find("owner:1")=forged;check(!validate_private_shop_cached_results(ended,&ledger).ok,"removed action cannot masquerade as unfinished");}
std::cout<<(failed?"FAIL":"PASS")<<'\n';return failed?1:0;}
